-- ============================================================
-- SAE / VISTA — Migración: Expresión de Interés + Código de Subasta
-- Ejecutar en Supabase SQL Editor (proyecto niemyawlnebylpidfefh)
-- ============================================================

-- 1) Nuevas columnas en la tabla existente inventario_SAE
ALTER TABLE inventario_SAE ADD COLUMN IF NOT EXISTS expresion_interes boolean NOT NULL DEFAULT false;
ALTER TABLE inventario_SAE ADD COLUMN IF NOT EXISTS codigo_subasta text;

-- 2) Reiniciar expresion_interes (por si se re-ejecuta esta migración)
UPDATE inventario_SAE SET expresion_interes = false;

